    /// it only needs a type that implements core::fmt::Write.
    pub fn signal(beacon: &mut Beacon, tower: u8, lit: bool) -> fmt::Result {
        write!(beacon, "tower {tower}: {}", if lit { "lit" } else { "dark" })
    }
